import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import fs from 'fs';
import path from 'path';
import { createScene } from './data/object.js';

// Create the scene graph
const root = createScene();

// Apply -90 degree X rotation for Blender Z-up coordinate system
// Wrap root in a parent so the rotation becomes part of the world matrix
const exportRoot = new THREE.Group();
exportRoot.rotation.x = -Math.PI / 2;
exportRoot.add(root);

// Update all world matrices
exportRoot.updateMatrixWorld(true);

// Collect all geometry with world transforms baked in.
// OBJExporter handles regular Meshes fine, but InstancedMesh needs
// to be expanded into individual meshes manually.
const exportScene = new THREE.Scene();

exportRoot.traverse((obj) => {
  if (obj instanceof THREE.InstancedMesh) {
    // Expand each instance into a standalone mesh
    const geo = obj.geometry;
    const count = obj.count;
    const instanceMatrix = new THREE.Matrix4();

    for (let i = 0; i < count; i++) {
      obj.getMatrixAt(i, instanceMatrix);

      // Full world transform: parent world matrix * instance local matrix
      const worldMatrix = new THREE.Matrix4();
      worldMatrix.multiplyMatrices(obj.matrixWorld, instanceMatrix);

      const clonedGeo = geo.clone();
      clonedGeo.applyMatrix4(worldMatrix);

      // Check if determinant is negative (mirrored) and flip faces if so
      if (worldMatrix.determinant() < 0) {
        flipWindingOrder(clonedGeo);
      }

      const mesh = new THREE.Mesh(clonedGeo);
      mesh.name = obj.name + '_instance_' + i;
      exportScene.add(mesh);
    }
  } else if (obj instanceof THREE.Mesh) {
    const clonedGeo = obj.geometry.clone();
    clonedGeo.applyMatrix4(obj.matrixWorld);

    // If the world matrix has a negative determinant (odd number of axis flips),
    // the winding order is reversed — fix it so normals face outward.
    if (obj.matrixWorld.determinant() < 0) {
      flipWindingOrder(clonedGeo);
    }

    const mesh = new THREE.Mesh(clonedGeo);
    mesh.name = obj.name;
    exportScene.add(mesh);
  }
});

function flipWindingOrder(geometry) {
  const index = geometry.getIndex();
  if (index) {
    const arr = index.array;
    for (let i = 0; i < arr.length; i += 3) {
      const tmp = arr[i + 1];
      arr[i + 1] = arr[i + 2];
      arr[i + 2] = tmp;
    }
    index.needsUpdate = true;
  }
  // Flip normals
  const normal = geometry.getAttribute('normal');
  if (normal) {
    for (let i = 0; i < normal.count; i++) {
      normal.setXYZ(i, -normal.getX(i), -normal.getY(i), -normal.getZ(i));
    }
    normal.needsUpdate = true;
  }
}

// Export to OBJ
const exporter = new OBJExporter();
const objString = exporter.parse(exportScene);

// Ensure output directory exists
const outputDir = path.resolve('/root/output');
if (!fs.existsSync(outputDir)) {
  fs.mkdirSync(outputDir, { recursive: true });
}

const outputPath = path.join(outputDir, 'object.obj');
fs.writeFileSync(outputPath, objString);
console.log('Exported OBJ to:', outputPath);

